package br.edu.ifms.robotica.servlet;
import java.io.IOException;import java.sql.SQLException;import javax.servlet.*;import javax.servlet.annotation.*;import javax.servlet.http.*;import br.edu.ifms.robotica.dao.CoordenadorDAO;import br.edu.ifms.robotica.model.Coordenador;import br.edu.ifms.robotica.seguranca.SenhaUtil;import br.edu.ifms.robotica.util.UploadUtil;
@WebServlet("/admin/coordenadores") @MultipartConfig(maxFileSize=5242880) public class CoordenadorServlet extends HttpServlet{private final CoordenadorDAO dao=new CoordenadorDAO();
 @Override protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{try{r.setAttribute("coordenadores",dao.listar());r.getRequestDispatcher("/WEB-INF/views/admin/coordenadores.jsp").forward(r,p);}catch(SQLException e){throw new ServletException(e);}}
 @Override protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{r.setCharacterEncoding("UTF-8");String a=r.getParameter("acao");try{if("inativar".equals(a)||"reativar".equals(a)){Long id=Long.valueOf(r.getParameter("id"));dao.alterarAtivo(id,"reativar".equals(a));p.sendRedirect(r.getContextPath()+"/admin/coordenadores?sucesso="+a);return;}Coordenador c=new Coordenador();if("editar".equals(a))c.setId(Long.valueOf(r.getParameter("id")));c.setNome(obrigatorio(r,"nome"));c.setMinibio(r.getParameter("minibio"));c.setEmail(obrigatorio(r,"email"));if(dao.emailEmUso(c.getEmail(),c.getId())){erro(r,p,"erro.email.duplicado");return;}c.setFoto(UploadUtil.salvar(r.getPart("foto"),"coordenadores",c.getNome()));if("editar".equals(a))dao.atualizar(c);else{c.setSenhaHash(SenhaUtil.gerarHash(r.getParameter("senha")));dao.inserir(c);}p.sendRedirect(r.getContextPath()+"/admin/coordenadores?sucesso="+("editar".equals(a)?"alteracao":"cadastro"));}catch(IllegalArgumentException e){erro(r,p,e.getMessage());}catch(SQLException e){throw new ServletException("Erro ao processar coordenador.",e);}}
 private String obrigatorio(HttpServletRequest r,String n){String v=r.getParameter(n);if(v==null||v.isBlank())throw new IllegalArgumentException("erro.campo.obrigatorio");return v.trim();}private void erro(HttpServletRequest r,HttpServletResponse p,String e)throws ServletException,IOException{r.setAttribute("erro",e);doGet(r,p);}}
